document.addEventListener("DOMContentLoaded",function(){const e=document.querySelectorAll(".carousel-slide"),t=document.querySelectorAll(".indicator"),c=document.querySelector(".carousel-control.prev"),n=document.querySelector(".carousel-control.next");let o=0;function l(){e.forEach((e,t)=>{e.classList.toggle("active",t===o)}),t.forEach((e,t)=>{e.classList.toggle("active",t===o)})}function r(){o=(o+1)%e.length,l()}n.addEventListener("click",r),c.addEventListener("click",function(){o=(o-1+e.length)%e.length,l()}),t.forEach((e,t)=>{e.addEventListener("click",()=>{o=t,l()})}),setInterval(r,5e3)});